mapper.select:
SELECT

FROM quality_inspection
WHERE 1=1

    AND project_id = #{param.projectId}


    AND inspection_no LIKE '%' || #{param.inspectionNo} || '%'


    AND inspection_name LIKE '%' || #{param.inspectionName} || '%'


    AND inspection_type = #{param.inspectionType}


    AND inspector_id = #{param.inspectorId}


    AND check_result = #{param.checkResult}


    AND rectification_status = #{param.rectificationStatus}


    AND rectification_person_id = #{param.rectificationPersonId}


    AND recheck_person_id = #{param.recheckPersonId}


    AND recheck_result = #{param.recheckResult}


    AND inspection_date >= #{param.inspectionStartDate}


    AND inspection_date <= #{param.inspectionEndDate}


    AND rectification_deadline >= #{param.rectificationDeadlineStart}


    AND rectification_deadline <= #{param.rectificationDeadlineEnd}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}


    AND (inspection_no LIKE '%' || #{param.keyword} || '%'
         OR inspection_name LIKE '%' || #{param.keyword} || '%'
         OR inspection_scope LIKE '%' || #{param.keyword} || '%'
         OR identified_issues LIKE '%' || #{param.keyword} || '%')

ORDER BY create_time DESC, id DESC

SELECT COUNT(*)
FROM quality_inspection
WHERE check_result = #{checkResult}

SELECT COUNT(*)
FROM quality_inspection
WHERE rectification_status = #{rectificationStatus}

SELECT

FROM quality_inspection
WHERE 1=1

    AND inspection_date >= #{startDate}


    AND inspection_date <= #{endDate}

ORDER BY inspection_date DESC
